#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_preorder_display_non_empty_tree(void) {
    node *root = NULL;
    int values[] = {10, 5, 15, 3, 7, 12, 18};
    int size = sizeof(values) / sizeof(values[0]);

    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    // Capture stdout output
    FILE *original_stdout = stdout;
    FILE *temp_file = tmpfile();
    if (temp_file == NULL) {
        TEST_FAIL_MESSAGE("Failed to create temporary file for stdout capture");
        return;
    }
    stdout = temp_file;
    setbuf(stdout, NULL);

    preorder_display(root);
    fflush(stdout);

    // Restore stdout and read captured output
    stdout = original_stdout;
    fseek(temp_file, 0, SEEK_END);
    long file_size = ftell(temp_file);
    fseek(temp_file, 0, SEEK_SET);

    char *output = malloc(file_size + 1);
    if (output == NULL) {
        TEST_FAIL_MESSAGE("Failed to allocate memory for captured output");
        fclose(temp_file);
        free_tree(root);
        return;
    }
    fread(output, 1, file_size, temp_file);
    output[file_size] = '\0';
    fclose(temp_file);

    TEST_ASSERT_NOT_NULL(output);
    TEST_ASSERT_NOT_NULL(strstr(output, "10"));
    TEST_ASSERT_NOT_NULL(strstr(output, "5"));
    TEST_ASSERT_NOT_NULL(strstr(output, "15"));

    free(output);
    free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_preorder_display_non_empty_tree);
    return UNITY_END();
}

